`ifdef RTL
	`define CYCLE_TIME_clk1 14.1
	`define CYCLE_TIME_clk2 10.1
	`define CYCLE_TIME_clk3 20.7
	`define PATTERN_NUM 100
`endif
`ifdef GATE
	`define CYCLE_TIME_clk1 14.1
	`define CYCLE_TIME_clk2 10.1
	`define CYCLE_TIME_clk3 20.7
	`define PATTERN_NUM 100
`endif

module PATTERN(
	clk1,
	clk2,
	clk3,
	rst_n,
	in_valid,
	in_data,
	out_valid,
	out_data
);

//---------------------------------------------------------------------
//   PORT DECLARATION          
//---------------------------------------------------------------------
output reg        clk1, clk2, clk3;
output reg        rst_n;
output reg        in_valid;
output reg [31:0] in_data;

input             out_valid;
input      [15:0] out_data;


//---------------------------------------------------------------------
//   PARAMETER & INTEGER
//---------------------------------------------------------------------
real	CYCLE_clk1 = `CYCLE_TIME_clk1;
real	CYCLE_clk2 = `CYCLE_TIME_clk2;
real	CYCLE_clk3 = `CYCLE_TIME_clk3;
integer total_latency;
integer latency;

integer pat_num = `PATTERN_NUM;
integer cur_pat;
integer read_status;
integer file_INPUT;
integer file_golden_ans;
integer this_pattern;

//---------------------------------------------------------------------
//   REG & WIRE
//---------------------------------------------------------------------
reg [3:0] x_input[0:127];
reg [15:0] golden_ans[0:127];

//---------------------------------------------------------------------
//  CLOCK
//---------------------------------------------------------------------
initial clk1 = 0;
always #(CYCLE_clk1/2.0) clk1 = ~clk1;

initial clk2 = 0;
always #(CYCLE_clk2/2.0) clk2 = ~clk2;

initial clk3 = 0;
always #(CYCLE_clk3/2.0) clk3 = ~clk3;

//---------------------------------------------------------------------
//  INITIAL
//---------------------------------------------------------------------
initial begin
	//#########################
	//       FILE I/O
	//#########################
	file_INPUT = $fopen("../00_TESTBED/NTT_input.txt", "r");
    file_golden_ans = $fopen("../00_TESTBED/NTT_golden_ans.txt", "r");

    if (file_INPUT == 0 || file_golden_ans == 0) begin
        $display("**************************************************");
        $display("                    SPEC-1 FAIL                   ");
        $display("                 File open failed!                ");
        $display("**************************************************");
        #(CYCLE_clk3*10);
        $finish;
    end
	//#########################
	//     START PATTERN
	//#########################
	reset_task;
	// Add your pattern here
	for (cur_pat = 0; cur_pat < pat_num; cur_pat = cur_pat + 1) begin
		integer gap;
		gap = $urandom_range(1,3);
        repeat(gap) @(negedge clk1);
		input_task;
		wait_task;
		latency = 0;
		check_ans_task;
		
		$display("\033[0;34mPASS PATTERN NO.%4d,\033[m \033[m \033[0;32mexecution cycle : %3d\033[m",cur_pat, latency);
	end
	// You can add more test cases if needed

	//#########################
	//       FILE CLOSE
	//#########################
	$fclose(file_INPUT);
	$fclose(file_golden_ans);

	//#########################
	//       YOU PASS
	//#########################
	YOU_PASS_task;
end

//---------------------------------------------------------------------
//  TASK
//---------------------------------------------------------------------
task reset_task; begin
    force clk1 = 0;
    force clk2 = 0;
    force clk3 = 0;
    rst_n = 1;
    in_valid = 0;

    total_latency = 0;

    #5 rst_n = 0;
    #100 rst_n = 1;
    if (out_valid !== 0 || out_data !== 0) begin
        $display("==========================================================================");
        $display("    Output signal should be 0 at %-12d ps  ", $time*1000);
        $display("==========================================================================");
        repeat(5) #(CYCLE_clk1);
        $finish;
    end	

    #(CYCLE_clk1/2.0);
    release clk1;
    release clk2;
    release clk3;
end endtask

task input_task; begin
	read_status = $fscanf(file_INPUT, "PATTERN: %d", this_pattern);
	if (this_pattern-1 !== cur_pat) begin
		
		$display("===============================================");
		$display("    Pattern number is not correct!            ");
		$display("    Expected: %d, Found: %d                   ", cur_pat, this_pattern);
		$display("===============================================");
		repeat(5) #(CYCLE_clk1);
		$finish;
	end

	// Read input data
	for (integer i = 0; i < 128; i = i + 1) begin
		read_status = $fscanf(file_INPUT, "%d", x_input[i]);
	end
	for (integer i = 0; i < 16; i = i + 1) begin
		in_valid = 1;
		in_data = {x_input[i*8 + 7], x_input[i*8 + 6], x_input[i*8 + 5], x_input[i*8 + 4], x_input[i*8 + 3], x_input[i*8 + 2], x_input[i*8 + 1], x_input[i*8 + 0]};
		@(negedge clk1);
	end

	in_valid = 0;
	in_data = 'bx;

end endtask

task wait_task; begin
	latency = -1;
	// Wait until out_valid is high
	while (latency < 5000) begin
		if(out_valid === 1) begin
			break;
		end 
		latency = latency + 1;
		@(negedge clk3);
	end 
	if (latency == 5000) begin
		display_fail;
		$display("**************************************************");
        $display("                    Pattern %d"  					, cur_pat);
		$display("                    SPEC-7 FAIL                   ");
		$display("             Latency is more than 5000!           ");
		$display("**************************************************");
		repeat(5) @(negedge clk3);
		$finish;
	end
end endtask

task check_ans_task; 
	integer out_count;
begin
	read_status = $fscanf(file_golden_ans, "PATTERN: %d", this_pattern);
	if (this_pattern-1 !== cur_pat) begin
		
		$display("===============================================");
		$display("    Pattern number is not correct!            ");
		$display("    Expected: %d, Found: %d                   ", cur_pat, this_pattern);
		$display("===============================================");
		repeat(5) #(CYCLE_clk1);
		$finish;
	end

	// Read input data
	for (integer i = 0; i < 128; i = i + 1) begin
		read_status = $fscanf(file_golden_ans, "%d", golden_ans[i]);
	end
	
	out_count = 0;
	while (out_count < 128) begin
		if (out_valid === 1) begin
			if (out_data !== golden_ans[out_count]) begin
				display_fail;
				$display("**************************************************");
				$display("                Pattern %d" 					, cur_pat);
				$display("                    SPEC-9 FAIL                   ");
				$display("             YOUR OUTPUT IS INCORRECT!             ");
				$display("             At index   : %d                  ", out_count);
				$display("             Your output: %d                          ", out_data);
				$display("             Golden ans : %d                          ", golden_ans[out_count]);
				$display("**************************************************");
				repeat(5) @(negedge clk3);
				$finish;
			end
			out_count = out_count + 1;
		end

		@(negedge clk3);
		latency = latency + 1;
		if (latency == 5000) begin
			display_fail;
			$display("**************************************************");
			$display("                    Pattern %d"  					, cur_pat);
			$display("                    SPEC-7 FAIL                   ");
			$display("             Latency is more than 5000!           ");
			$display("**************************************************");
			repeat(5) @(negedge clk3);
			$finish;
		end	
	end
	total_latency = total_latency + latency;
end endtask

